dashboard.definition:
{
    "title": "Splunk Allgemeines Krankenhaus – Lagebild",
    "description": "Klinik-Uebersicht des SAKH: freie Betten je Haus und Station, Versorgungslage und Infrastruktur-Gesundheit",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_beds": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:kis:beds\" earliest=-15m\n| stats latest(beds_total) as beds_total latest(occupied) as occupied latest(free) as free latest(occupancy_pct) as occupancy_pct latest(floor) as floor latest(ward_name) as ward_name by ward building department",
                "enableSmartSources": true
            },
            "name": "Bettenstatus (letzte 15 min)"
        },
        "ds_k_free": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_beds",
                "query": "| stats sum(free) as \"Freie Betten\""
            }
        },
        "ds_k_occ": {
            "type": "ds.search",
            "options": {
                "query": "| mstats sum(sakh.beds.occupied) as o sum(sakh.beds.beds_total) as t WHERE index=demo_sakh_metrics span=15m\n| eval \"Belegung %\"=round(100 * o / t, 1) | fields _time \"Belegung %\"",
                "enableSmartSources": true
            },
            "name": "Belegung Verlauf"
        },
        "ds_k_ed": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as w WHERE index=demo_sakh_metrics metric_name=\"sakh.ed.waiting\" span=10m | rename w as \"Wartend\"",
                "enableSmartSources": true
            }
        },
        "ds_k_blood": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:bloodbank:inventory\" earliest=-20m | stats latest(status) as status by product blood_group | where status=\"kritisch\" | stats count as \"Kritische Blutbestaende\"",
                "enableSmartSources": true
            }
        },
        "ds_k_inc": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:incident\" earliest=-48h | stats latest(state) as state latest(priority) as priority by number | where priority<=2 AND state!=\"Geloest\" | stats count as \"Offene P1/P2\"",
                "enableSmartSources": true
            }
        },
        "ds_k_net": {
            "type": "ds.search",
            "options": {
                "query": "| mstats latest(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.network.reachable\" BY device | where v=0 | stats count as \"Netzwerk offline\"",
                "enableSmartSources": true
            }
        },
        "ds_rings": {
            "type": "ds.search",
            "options": {
                "query": "| mstats latest(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.beds.occupancy_pct\" BY ward\n| stats avg(v) as beds\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.ed.waiting\" | stats max(v) as ed]\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.blood.fill_pct\" product=\"EK\" BY blood_group | stats min(v) as blood]\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.medtech.online\" BY device_id | stats avg(v) as medtech | eval medtech=round(100*medtech, 1)]\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.network.reachable\" BY device | stats avg(v) as net | eval net=round(100*net, 1)]\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.hl7.queue_depth\" BY channel | stats sum(v) as hl7]\n| appendcols [| mstats latest(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.db.avg_query_ms\" instance=\"KISPRD\" | stats max(v) as kisdb]\n| eval r=mvappend(\"Bettenbelegung;\".coalesce(tostring(round(beds, 1)), \"\").\";%;0;100;88;95;lower;kis_beds\", \"Notaufnahme wartend;\".coalesce(tostring(ed), \"\").\";;0;80;15;30;lower;kis_ed\", \"Blut EK min. Fuellung;\".coalesce(tostring(round(blood, 0)), \"\").\";%;0;120;45;25;higher;kis_blood\", \"Medizintechnik online;\".coalesce(tostring(medtech), \"\").\";%;0;100;98;90;higher;kis_medtech\", \"Netzwerk erreichbar;\".coalesce(tostring(net), \"\").\";%;0;100;99;95;higher;kis_network\", \"HL7 Warteschlange;\".coalesce(tostring(hl7), \"\").\";;0;500;50;200;lower;kis_integration\", \"KIS-DB Abfrage;\".coalesce(tostring(round(kisdb, 0)), \"\").\";ms;0;200;20;60;lower;kis_servers\")\n| mvexpand r\n| eval f=split(r, \";\"), name=mvindex(f, 0), value=mvindex(f, 1), unit=mvindex(f, 2), min=mvindex(f, 3), max=mvindex(f, 4), warn=mvindex(f, 5), crit=mvindex(f, 6), better=mvindex(f, 7), key=mvindex(f, 8)\n| table name value unit min max warn crit better key",
                "enableSmartSources": true
            },
            "name": "Gesundheit je Bereich"
        },
        "ds_trend": {
            "type": "ds.search",
            "options": {
                "query": "| mstats sum(sakh.beds.occupied) as o sum(sakh.beds.beds_total) as t WHERE index=demo_sakh_metrics BY building span=15m\n| eval pct=round(100 * o / t, 1), building=\"Haus \".building\n| timechart span=15m avg(pct) by building",
                "enableSmartSources": true
            },
            "name": "Belegung je Haus"
        },
        "ds_incidents": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:incident\" earliest=-48h\n| stats latest(state) as Status latest(priority_label) as Prioritaet latest(short_description) as Beschreibung latest(assignment_group) as Gruppe latest(business_service) as Service latest(_time) as t by number\n| where Status!=\"Geloest\" | sort Prioritaet - t | head 12\n| eval Zeit=strftime(t, \"%d.%m. %H:%M\") | table Zeit number Prioritaet Status Service Gruppe Beschreibung | rename number as Incident",
                "enableSmartSources": true
            },
            "name": "Offene Incidents"
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
